  var EXPR = ['smile','wink','curious','wow','love','excited','confused','sad','angry','sleepy','joy','laugh','shy','cool','kiss','dance','dizzy','sigh','boing','hop'];
  var SON = ['smile','wink','curious','wow','love','yawn','excited','confused','sad','angry','sleepy','joy','laugh','shy','cool','kiss','tap','boing','sparkle','hop','sigh','dance'];
  var actual = null, bolsa = [], anterior = -1, timer = null;

  function categoria(i) {
    return Math.floor((i - 1) / 50);
  }
  function familia(i, nombre) {
    var n = String(nombre).toLowerCase();
    var c = categoria(i);
    if (c === 0) return ['sad','sigh','confused','shy','sleepy'];
    if (c === 1) return ['wow','angry','dizzy','laugh','sad'];
    if (c === 2) return ['sleepy','yawn','sigh','confused','smile'];
    if (c === 3) return ['angry','boing','dizzy','wow','sigh'];
    if (c === 4) return ['cool','angry','wink','dance','smile'];
    if (c === 5) return ['love','smile','joy','shy','wink'];
    if (c === 6) return ['laugh','wink','boing','joy','dance'];
    if (c === 7) return ['dizzy','wow','laugh','boing','dance'];
    if (c === 8) return ['cool','wink','confused','laugh','smirk'];
    if (c === 9) return ['sleepy','sigh','confused','smile','wink'];
    if (c === 10) return ['curious','wow','thinking','confused','excited'];
    if (c === 11) return ['wink','laugh','boing','curious','dance'];
    if (c === 12) return ['cool','sad','curious','shy','confused'];
    if (c === 13) return ['excited','cool','angry','laugh','dance'];
    if (c === 14) return ['dance','joy','cool','excited','smile'];
    if (c === 15) return ['thinking','cool','confused','curious','wow'];
    if (c === 16) return ['shy','curious','sad','smile','wink'];
    if (c === 17) return ['cool','wink','wow','smile','laugh'];
    if (c === 18) return ['love','smile','joy','shy','wink'];
    return ['curious','wow','confused','cool','dream'];
  }
  function limpiar(a) { return a.filter(function(x){ return EXPR.indexOf(x) >= 0; }); }
  function crearPerfil(p) {
    var e = limpiar(familia(p.id, p.nombre));
    while (e.length < 5) e.push(EXPR[(p.id + e.length * 7) % EXPR.length]);
    var s = [];
    for (var j=0;j<5;j++) s.push(SON[(p.id * 3 + j * 5) % SON.length]);
    return { id:p.id, nombre:p.nombre, categoria:p.categoria, reacciones:e.slice(0,5), sonidos:s, intensidad:0.55 + ((p.id*17)%40)/100, pausa:26000 + ((p.id*29)%26000) };
  }

  PERSONALIDADES = PERSONALIDADES.map(crearPerfil);
  var porId = Object.create(null);
  PERSONALIDADES.forEach(function(p){ porId[p.id] = p; });

  function mezclar(a) {
    for (var i=a.length-1;i>0;i--) {
      var k=Math.floor(Math.random()*(i+1)), t=a[i]; a[i]=a[k]; a[k]=t;
    }
    if (a.length && a[a.length-1] === anterior) {
      var t2=a[0]; a[0]=a[a.length-1]; a[a.length-1]=t2;
    }
  }
  function siguiente() {
    if (!bolsa.length) {
      bolsa = PERSONALIDADES.map(function(p){ return p.id; });
      mezclar(bolsa);
    }
    anterior = bolsa.pop();
    return porId[anterior];
  }
  function visible(c){ return !!(c.offsetParent || (c.getClientRects && c.getClientRects().length)); }
  function aplicar(p, forzado) {
    if (!p) return;
    actual = p;
    document.documentElement.setAttribute('data-osito-personality', String(p.id));
    document.querySelectorAll('.osito-face').forEach(function(c){
      c.setAttribute('data-personality-id', String(p.id));
      c.setAttribute('data-personality', p.nombre);
      c.title = 'Personalidad: ' + p.nombre;
      c.setAttribute('aria-label', 'Osito — personalidad: ' + p.nombre);
    });
    if (document.body) {
      document.body.setAttribute('data-osito-personality', p.nombre);
    }
    // Una personalidad activa siempre tiene 5 posibles reacciones propias.
    var r = p.reacciones[(p.id + Math.floor(Date.now()/1000)) % p.reacciones.length];
    if ((r === 'sleepy' || r === 'yawn') && (!window.OsitoNight || !window.OsitoNight.esNoche || !window.OsitoNight.esNoche())) r = 'smile';
    if ((r === 'sleepy' || r === 'yawn') && window.OsitoNight && window.OsitoNight.duerme && window.OsitoNight.duerme()) r = 'smile';
    F.paraTodas(r, forzado ? 2400 : 1900);
    if (window.OsitoPersonalidadAnim && window.OsitoPersonalidadAnim.aplicar) window.OsitoPersonalidadAnim.aplicar(p.id, forzado);
    // El cambio de personalidad produce sonido. El sonido exacto varía por perfil.
    if (S && S.reproducir) {
      var sn = p.sonidos[(p.id + Math.floor(Date.now()/1000)) % p.sonidos.length];
      setTimeout(function(){ if (S.reproducir) S.reproducir(sn); }, 40);
    }
    if (S && S.reproducirExtra) setTimeout(function(){ S.reproducirExtra((p.id - 1) % 100); }, 90);
    window.dispatchEvent(new CustomEvent('osito:personalidad', { detail:p }));
  }

  function puedeCambiar(){
    if (document.hidden || window.ositoEnLlamadaIA || document.documentElement.classList.contains('ia-speaking-mode')) return false;
    if (document.body && (document.body.classList.contains('no-animations') || document.body.classList.contains('ultra-performance'))) return false;
    if (window.OsitoNight && window.OsitoNight.duerme && window.OsitoNight.duerme()) return false;
    // V59: mientras Osito está con un objeto, no se cambia de personalidad (pisaría su expresión lenta).
    if (document.querySelector('.osito-face[data-boredom]')) return false;
    return true;
  }
  function programar(){
    clearTimeout(timer);
    var p = siguiente();
    var espera = p.pausa;
    timer = setTimeout(function(){
      if (puedeCambiar()) aplicar(p, false);
      programar();
    }, espera);
  }

  // Primera personalidad: una de las 1,000, sin repetir hasta terminar la bolsa.
  aplicar(siguiente(), true);
  programar();

  window.OsitoPersonalidades = {
    todas: PERSONALIDADES,
    cantidad: PERSONALIDADES.length,
    actual: function(){ return actual; },
    siguiente: function(){ var p=siguiente(); aplicar(p,true); return p; },
    activar: function(id){ var p=porId[Number(id)]; if(!p) return null; aplicar(p,true); return p; },
    buscar: function(q){ q=String(q||'').toLowerCase(); return PERSONALIDADES.filter(function(p){ return p.nombre.toLowerCase().indexOf(q)>=0; }); }
  };
